INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5000, 'point', '/pɔɪnt/', 'noun', '{"zh-TW":["要點；觀點","分數"],"en":["a key idea","a unit of scoring"]}', NULL, 'make a point / point out / turning point / to the point', '[{"en":"She made an excellent point in the meeting.","zh-TW":"她在會議上提出了很好的觀點。"},{"en":"I''d like to point out a few issues.","zh-TW":"我想指出幾個問題。"}]', '{"verb":"point","adjective":"pointed"}', NULL, 2, 5000, NULL),
(5001, 'point of sale', '/pɔɪnt əv seɪl/', 'noun', '{"zh-TW":["銷售點；結帳點"],"en":["the location and time where a purchase occurs"]}', NULL, 'point of sale system / point of sale display', '[{"en":"The new point of sale system speeds up checkout.","zh-TW":"新的銷售點系統加快了結帳速度。"},{"en":"Promotional materials placed at the point of sale boost impulse purchases.","zh-TW":"放置在銷售點的促銷材料促進了衝動購買。"}]', '{"abbreviation":"POS"}', NULL, 5, 5001, NULL),
(5002, 'polarization', '/ˌpəʊlərɪˈzeɪʃən/', 'noun', '{"zh-TW":["極化；兩極化"],"en":["the division into two sharply contrasting groups or sets of opinions"]}', NULL, 'economic polarization / social polarization / reduce polarization', '[{"en":"Economic polarization between rich and poor has increased in many countries.","zh-TW":"許多國家貧富之間的經濟極化有所加劇。"},{"en":"Algorithmic curation contributes to information polarization online.","zh-TW":"算法策展導致了線上資訊極化。"}]', '{"verb":"polarize","adjective":"polarized"}', NULL, 4, 5002, NULL),
(5003, 'polarize', '/ˈpəʊləraɪz/', 'verb', '{"zh-TW":["兩極化；使對立"],"en":["to divide into two sharply contrasting groups or sets of opinions"]}', NULL, 'polarize opinion / polarize society / polarize debate', '[{"en":"The policy debate has polarized public opinion.","zh-TW":"政策辯論使公眾意見兩極化。"},{"en":"Social media tends to polarize rather than unite communities.","zh-TW":"社交媒體往往使社區兩極化而非團結。"}]', '{"noun":"polarization","adjective":"polarized"}', NULL, 3, 5003, NULL),
(5004, 'policy', '/ˈpɒlɪsi/', 'noun', '{"zh-TW":["政策；方針"],"en":["a plan of action adopted by an organization"]}', '{"root":{"text":"poli","meaning":"city, state (國家)"}}', 'company policy / insurance policy / implement a policy', '[{"en":"The new policy takes effect next month.","zh-TW":"新政策下月生效。"},{"en":"It is against company policy to accept gifts.","zh-TW":"接受禮物違反公司政策。"}]', '{"noun":"policyholder"}', NULL, 2, 5004, 45),
(5005, 'policy compliance', '/ˈpɒlɪsi kəmˈplaɪəns/', 'noun', '{"zh-TW":["政策合規；政策遵從"],"en":["adherence to established organizational rules and guidelines"]}', NULL, 'ensure policy compliance / policy compliance training', '[{"en":"All staff must complete policy compliance training annually.","zh-TW":"所有員工每年必須完成政策合規培訓。"},{"en":"An internal audit checked policy compliance across all departments.","zh-TW":"內部審計檢查了所有部門的政策合規情況。"}]', NULL, NULL, 5, 5005, NULL),
(5006, 'policy update', '/ˈpɒlɪsi ˈʌpdeɪt/', 'noun', '{"zh-TW":["政策更新"],"en":["a revision or change to an existing policy document"]}', NULL, 'issue a policy update / communicate the policy update', '[{"en":"A policy update was sent to all employees regarding travel expenses.","zh-TW":"關於差旅費的政策更新已發送給所有員工。"},{"en":"The policy update reflected new regulatory requirements.","zh-TW":"政策更新反映了新的監管要求。"}]', NULL, NULL, 5, 5006, NULL),
(5007, 'policyholder', '/ˈpɒlɪsiˌhoʊldər/', 'noun', '{"zh-TW":["保單持有人；被保險人"],"en":["a person or organization that holds an insurance policy"]}', NULL, 'rights of the policyholder / policyholder claims', '[{"en":"The policyholder must notify the insurer within 48 hours of an incident.","zh-TW":"保單持有人必須在事故發生後48小時內通知保險公司。"},{"en":"All policyholders received a notice about the rate increase.","zh-TW":"所有保單持有人都收到了費率上調的通知。"}]', NULL, NULL, 4, 5007, NULL),
(5008, 'political polarization', '/pəˈlɪtɪkəl ˌpəʊlərɪˈzeɪʃən/', 'noun', '{"zh-TW":["政治極化"],"en":["the divergence of political attitudes to ideological extremes"]}', NULL, 'increase political polarization / counter political polarization / political polarization crisis', '[{"en":"Social media is frequently cited as a driver of political polarization.","zh-TW":"社交媒體常被引用為政治極化的驅動力。"},{"en":"Political polarization makes compromise and bipartisan legislation more difficult.","zh-TW":"政治極化使妥協和兩黨立法變得更加困難。"}]', '{"adjective":"politically polarized"}', NULL, 5, 5008, NULL),
(5009, 'poll', '/poʊl/', 'noun', '{"zh-TW":["民調；投票","民調"],"en":["a survey of public opinion","a survey of opinion"]}', NULL, 'opinion poll / conduct a poll / go to the polls; opinion poll / exit poll / poll results', '[{"en":"The latest poll shows strong support.","zh-TW":"最新民調顯示強力支持。"},{"en":"We conducted a poll among employees.","zh-TW":"我們在員工中進行了調查。"},{"en":"According to the latest polls, support is growing.","zh-TW":"根據最新民調，支持率正在增長。"},{"en":"Exit polls predict a close race.","zh-TW":"出口民調預測競爭激烈。"}]', '{"noun":"pollster","verb":"poll"}', NULL, 1, 5009, NULL),
(5010, 'pollinator', '/ˈpɒlɪneɪtər/', 'noun', '{"zh-TW":["授粉者；傳粉者"],"en":["an animal that carries pollen from one plant to another"]}', NULL, 'protect pollinators / decline in pollinators / native pollinator', '[{"en":"Bees and butterflies are essential pollinators for food crops.","zh-TW":"蜜蜂和蝴蝶是糧食作物的重要授粉者。"},{"en":"The decline of pollinators threatens global food production.","zh-TW":"授粉者的減少威脅著全球糧食生產。"}]', '{"verb":"pollinate","noun2":"pollination"}', NULL, 4, 5010, NULL),
(5011, 'pollutant', '/pəˈluːtənt/', 'noun', '{"zh-TW":["污染物"],"en":["a substance that contaminates air, water, or soil"]}', NULL, 'release pollutants / pollutant levels / restrict pollutants', '[{"en":"Stricter standards limit the pollutants that factories can discharge.","zh-TW":"更嚴格的標準限制了工廠可以排放的污染物。"},{"en":"Some pollutants persist in the environment for decades.","zh-TW":"一些污染物在環境中持續存在數十年。"}]', '{"verb":"pollute","noun2":"pollution","adjective":"polluting"}', NULL, 3, 5011, NULL),
(5012, 'pollution', '/pəˈluːʃən/', 'noun', '{"zh-TW":["污染"],"en":["the presence of harmful substances in the environment"]}', NULL, 'air pollution / water pollution', '[{"en":"Air pollution is a serious health concern in major cities.","zh-TW":"空氣污染是大城市中嚴重的健康問題。"},{"en":"Industrial activities are a leading cause of water pollution.","zh-TW":"工業活動是水污染的主要原因。"}]', '{"verb":"pollute","noun":"pollutant","adjective":"polluted"}', NULL, 3, 5012, NULL),
(5013, 'pool', '/puːl/', 'noun', '{"zh-TW":["資源池；共用資金"],"en":["a shared supply of resources"]}', NULL, 'pool resources / talent pool / car pool', '[{"en":"We need to pool our resources for this project.","zh-TW":"我們需要集中資源做這項目。"},{"en":"The company maintains a talent pool.","zh-TW":"公司維護人才庫。"}]', '{"verb":"pool"}', NULL, 1, 5013, NULL),
(5014, 'poolside', '/ˈpuːlsaɪd/', 'noun', '{"zh-TW":["游泳池旁"],"en":["the area immediately beside a swimming pool"]}', NULL, 'relax poolside / poolside bar', '[{"en":"Guests can enjoy refreshments at the poolside bar.","zh-TW":"賓客可以在游泳池旁的酒吧享用飲料。"},{"en":"She spent the afternoon relaxing poolside with a good book.","zh-TW":"她下午在游泳池旁看書放鬆。"}]', NULL, NULL, 3, 5014, NULL),
(5015, 'poor', '/pʊr/', 'adjective', '{"zh-TW":["貧窮的；差的"],"en":["having little money","of low quality"]}', NULL, 'poor performance / poor quality', '[{"en":"Poor performance will be addressed.","zh-TW":"差的表現會被處理。"},{"en":"Sales were poor this quarter.","zh-TW":"本季銷售表現不佳。"}]', '{"adjective":"poor","adverb":"poorly","noun":"poverty"}', NULL, 1, 5015, NULL),
(5016, 'popular', '/ˈpɒpjʊlər/', 'adjective', '{"zh-TW":["受歡迎的；流行的"],"en":["liked by many people"]}', NULL, 'popular demand / popular choice', '[{"en":"Due to popular demand, we extended the sale.","zh-TW":"由於廣受歡迎，我們延長了促銷。"},{"en":"This is our most popular product.","zh-TW":"這是我們最受歡迎的產品。"}]', '{"adjective":"popular","noun":"popularity","verb":"popularize","adjective2":"unpopular"}', NULL, 3, 5016, NULL),
(5017, 'populism', '/ˈpɒpjʊlɪzəm/', 'noun', '{"zh-TW":["民粹主義"],"en":["a political approach appealing to ordinary people against a perceived elite"]}', NULL, 'rise of populism / left-wing populism / right-wing populism', '[{"en":"Populism often thrives in periods of economic insecurity and distrust of institutions.","zh-TW":"民粹主義往往在經濟不安全和對機構不信任的時期蓬勃發展。"},{"en":"Critics argue that populism oversimplifies complex policy challenges.","zh-TW":"批評者認為民粹主義過度簡化了複雜的政策挑戰。"}]', '{"adjective":"populist","noun2":"populist"}', NULL, 3, 5017, NULL),
(5018, 'port', '/pɔːrt/', 'noun', '{"zh-TW":["港口"],"en":["a town or city with a harbor for ships"]}', NULL, 'cruise port / home port', '[{"en":"The cruise docks at the port of Barcelona.","zh-TW":"郵輪停靠在巴塞隆納港。"},{"en":"The port handles millions of passengers each year.","zh-TW":"該港口每年接待數百萬名乘客。"}]', NULL, NULL, 1, 5018, NULL),
(5019, 'port congestion', '/''pɔːrt kənˌdʒestʃən/', 'noun', '{"zh-TW":["港口擁堵"],"en":["a situation where too many vessels arrive at a port at the same time, causing delays in loading and unloading"]}', NULL, 'deal with port congestion / port congestion delays / cause port congestion', '[{"en":"Port congestion during the holiday season led to weeks of shipping delays.","zh-TW":"假日季節的港口擁堵導致了數週的運輸延誤。"},{"en":"Authorities are investing in new infrastructure to reduce chronic port congestion.","zh-TW":"當局正在投資新的基礎設施，以減少長期的港口擁堵問題。"}]', '{"noun":"congestion","adjective":"congested"}', NULL, 5, 5019, NULL),
(5020, 'port of discharge', '/''pɔːrt əv dɪsˌtʃɑːrdʒ/', 'noun', '{"zh-TW":["目的地港；卸貨港"],"en":["the port at which cargo is unloaded from the ship"]}', NULL, 'destination port of discharge / port of discharge documentation / arrive at port of discharge', '[{"en":"The port of discharge was listed on the shipping documents as Rotterdam.","zh-TW":"卸貨港在運輸文件上被列為鹿特丹。"},{"en":"Delays at the port of discharge added two weeks to the delivery timeline.","zh-TW":"卸貨港的延誤使配送時間增加了兩週。"}]', NULL, NULL, 5, 5020, NULL),
(5021, 'port of entry', '/''pɔːrt əv ˈentri/', 'noun', '{"zh-TW":["入境口岸；入境港"],"en":["a place where people may lawfully enter a country, such as an airport or seaport"]}', NULL, 'designated port of entry / use a port of entry / major port of entry', '[{"en":"All international travelers must pass through a designated port of entry.","zh-TW":"所有國際旅客必須通過指定的入境口岸。"},{"en":"The city''s international airport is the busiest port of entry in the country.","zh-TW":"該市的國際機場是全國最繁忙的入境口岸。"}]', NULL, NULL, 5, 5021, NULL),
(5022, 'port of origin', '/pɔːrt əv ˈɒrɪdʒɪn/', 'noun', '{"zh-TW":["起運港；出發港"],"en":["the port from which a shipment starts its journey"]}', NULL, 'declare port of origin / port of origin documentation', '[{"en":"The goods were shipped from their port of origin in Shanghai.","zh-TW":"貨物從上海的起運港發運。"},{"en":"The port of origin must be declared on the shipping documents.","zh-TW":"起運港必須在運輸文件上申報。"}]', NULL, NULL, 5, 5022, NULL),
(5023, 'porter', '/ˈpɔːrtər/', 'noun', '{"zh-TW":["行李員；門房"],"en":["a person employed to carry luggage or manage a building entrance"]}', NULL, 'airport porter / hotel porter / luggage porter', '[{"en":"The hotel porter helped carry the heavy luggage to the room.","zh-TW":"酒店行李員幫忙將沉重的行李搬到房間。"},{"en":"Tipping the porter is customary in many countries.","zh-TW":"在許多國家給行李員小費是慣例。"}]', NULL, NULL, 2, 5023, NULL),
(5024, 'portfolio', '/pɔːrtˈfoʊlioʊ/', 'noun', '{"zh-TW":["投資組合；作品集"],"en":["a collection of investments or projects held by an entity"]}', NULL, 'investment portfolio / diversified portfolio / portfolio management', '[{"en":"He balanced his portfolio between stocks and bonds.","zh-TW":"他在股票和債券之間平衡了自己的投資組合。"},{"en":"The portfolio returned 12% over the past year.","zh-TW":"投資組合過去一年回報率為12%。"}]', '{"plural":"portfolios"}', NULL, 3, 5024, NULL),
(5025, 'portfolio company', '/pɔːrtˈfoʊlioʊ ˈkʌmpəni/', 'noun', '{"zh-TW":["投資組合公司"],"en":["a company owned or invested in by a private equity or investment fund"]}', NULL, 'manage a portfolio company / support portfolio companies', '[{"en":"The fund has 12 portfolio companies across various sectors.","zh-TW":"該基金在各行業擁有12家投資組合公司。"},{"en":"Portfolio company performance is reviewed quarterly by the fund.","zh-TW":"投資組合公司的績效由基金每季審查。"}]', NULL, NULL, 5, 5025, NULL),
(5026, 'portfolio diversification', '/pɔːrtˈfoʊlioʊ daɪˌvɜːrsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["投資組合多元化"],"en":["spreading investments across different assets to reduce risk"]}', NULL, 'achieve portfolio diversification / portfolio diversification strategy', '[{"en":"Portfolio diversification reduces the impact of any single investment loss.","zh-TW":"投資組合多元化降低了任何單一投資損失的影響。"},{"en":"The fund manager pursued portfolio diversification across five asset classes.","zh-TW":"基金管理人在五個資產類別中追求投資組合多元化。"}]', NULL, NULL, 5, 5026, NULL),
(5027, 'portfolio management', '/pɔːrtˈfoʊlioʊ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["投資組合管理"],"en":["the professional management of a collection of investments"]}', NULL, 'oversee portfolio management / portfolio management strategy', '[{"en":"Active portfolio management aims to beat the benchmark return.","zh-TW":"主動投資組合管理旨在超越基準回報。"},{"en":"The fund follows a passive portfolio management strategy.","zh-TW":"基金遵循被動投資組合管理策略。"}]', NULL, NULL, 5, 5027, NULL),
(5028, 'portfolio rebalancing', '/pɔːrtˈfəʊliəʊ ˌriːˈbælənsɪŋ/', 'noun', '{"zh-TW":["投資組合再平衡"],"en":["the process of realigning the weights of assets in a portfolio"]}', NULL, 'portfolio rebalancing strategy / trigger rebalancing / periodic rebalancing', '[{"en":"Portfolio rebalancing ensures the asset allocation stays on target.","zh-TW":"投資組合再平衡確保資產配置保持在目標水平。"},{"en":"Investors rebalance portfolios annually or when allocations drift significantly.","zh-TW":"投資者每年或當配置顯著偏離時進行再平衡。"}]', NULL, NULL, 5, 5028, NULL),
(5029, 'portion', '/ˈpɔːrʃən/', 'noun', '{"zh-TW":["部分；份額"],"en":["a part of something"]}', '{"root":{"text":"port","meaning":"part (部分)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'a large portion / portion of the budget', '[{"en":"A large portion of the budget goes to salaries.","zh-TW":"預算的大部分用於薪資。"},{"en":"Each team receives an equal portion.","zh-TW":"每個團隊獲得相等份額。"}]', NULL, NULL, 3, 5029, NULL),
(5030, 'portion control', '/''pɔːʃən kənˌtrəʊl/', 'noun', '{"zh-TW":["份量控制"],"en":["the practice of regulating the amount of food consumed at one time"]}', NULL, 'practice portion control / portion control strategy / benefit of portion control', '[{"en":"Portion control is one of the most effective strategies for weight management.","zh-TW":"份量控制是體重管理最有效的策略之一。"},{"en":"Using smaller plates can naturally aid portion control during meals.","zh-TW":"使用較小的盤子可以在用餐時自然地幫助份量控制。"}]', NULL, NULL, 5, 5030, NULL),
(5031, 'portion size', '/''pɔːʃən saɪz/', 'noun', '{"zh-TW":["份量大小；一份食物的量"],"en":["the amount of food that makes up one serving"]}', NULL, 'reduce portion size / appropriate portion size / generous portion size', '[{"en":"Reducing portion sizes is one of the most effective ways to cut calories.","zh-TW":"減少份量大小是減少卡路里攝取最有效的方法之一。"},{"en":"Many restaurant meals contain much larger portion sizes than recommended.","zh-TW":"許多餐廳的食物份量遠大於建議的量。"}]', NULL, NULL, 4, 5031, NULL),
(5032, 'portrait', '/ˈpɔːrtrɪt/', 'noun', '{"zh-TW":["肖像；人像畫"],"en":["a painting or photograph of a person"]}', '{"prefix":{"text":"por-","meaning":"forth (向前)"},"root":{"text":"trait","meaning":"draw (描繪)"},"logic":"向前描繪出來的形象，即「肖像」。"}', 'portrait painting / family portrait', '[{"en":"The artist painted a portrait of the queen.","zh-TW":"藝術家為女王畫了一幅肖像。"},{"en":"A family portrait hung on the wall.","zh-TW":"一幅全家福掛在牆上。"}]', '{"noun":"portraiture","verb":"portray"}', NULL, 3, 5032, NULL),
(5033, 'portrayal', '/pɔːˈtreɪəl/', 'noun', '{"zh-TW":["描繪；刻畫"],"en":["a description or representation of someone or something"]}', NULL, 'accurate portrayal / nuanced portrayal / media portrayal', '[{"en":"The film''s portrayal of mental illness was praised for its sensitivity.","zh-TW":"電影對心理疾病的描繪因其敏感性而受到讚揚。"},{"en":"Critics questioned the historical accuracy of the portrayal.","zh-TW":"評論家對描繪的歷史準確性提出質疑。"}]', '{"verb":"portray","adjective":"portrayed"}', NULL, 3, 5033, NULL),
(5034, 'pose', '/poʊz/', 'verb', '{"zh-TW":["構成；提出"],"en":["to present or constitute"]}', NULL, 'pose a threat / pose a question / pose a challenge', '[{"en":"This poses a serious threat to the business.","zh-TW":"這對業務構成嚴重威脅。"},{"en":"The new regulation poses challenges.","zh-TW":"新規定帶來挑戰。"}]', NULL, NULL, 1, 5034, NULL),
(5035, 'posit', '/ˈpɒzɪt/', 'verb', '{"zh-TW":["假設；假定；提出"],"en":["to put forward as fact or as a basis for argument"]}', NULL, 'posit a theory / posit that / posit an idea', '[{"en":"The paper posits that economic growth drives social change.","zh-TW":"論文假設經濟增長推動社會變革。"},{"en":"She posited a new model to explain the observed data.","zh-TW":"她提出了一個新模型來解釋觀察到的數據。"}]', NULL, NULL, 2, 5035, NULL),
(5036, 'position', '/pəˈzɪʃən/', 'noun', '{"zh-TW":["職位","位置","立場"],"en":["a job","a place","an opinion"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'apply for a position / market position / bargaining position', '[{"en":"She applied for the managerial position.","zh-TW":"她申請了管理職位。"},{"en":"The company holds a strong market position.","zh-TW":"公司擁有強勁的市場地位。"}]', '{"verb":"position"}', NULL, 3, 5036, 46),
(5037, 'position paper', '/pəˈzɪʃən ˈpeɪpər/', 'noun', '{"zh-TW":["立場文件；政策文件"],"en":["a document outlining an organization''s official stance on an issue"]}', NULL, 'prepare a position paper / submit a position paper', '[{"en":"The industry submitted a position paper opposing the new regulation.","zh-TW":"該行業提交了一份反對新法規的立場文件。"},{"en":"A position paper helps align stakeholders before a negotiation.","zh-TW":"立場文件有助於在談判前協調利害關係人。"}]', NULL, NULL, 5, 5037, NULL),
(5038, 'positioning', '/pəˈzɪʃənɪŋ/', 'noun', '{"zh-TW":["市場定位"],"en":["the process of creating a specific image in consumers'' minds"]}', NULL, 'brand positioning / market positioning / positioning strategy', '[{"en":"The company''s positioning as a premium brand justifies higher prices.","zh-TW":"公司作為高端品牌的定位是較高定價的依據。"},{"en":"Positioning the product for young professionals drove strong sales.","zh-TW":"將產品定位於年輕專業人士推動了強勁銷售。"}]', '{"verb":"position","adjective":"positioned"}', NULL, 4, 5038, NULL),
(5039, 'positive', '/ˈpɒzɪtɪv/', 'adjective', '{"zh-TW":["積極的；正面的","肯定的","積極的","確定的"],"en":["good; constructive","certain; sure","certain"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'positive feedback / positive impact / positive attitude; positive feedback / positive impact / test positive', '[{"en":"The feedback has been overwhelmingly positive.","zh-TW":"反饋非常正面。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極態度會帶來改變。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極的態度會帶來改變。"}]', '{"adverb":"positively","noun":"positivity"}', NULL, 3, 5039, NULL),
(5040, 'positive cash flow', '/ˈpɒzɪtɪv kæʃ floʊ/', 'noun', '{"zh-TW":["正現金流"],"en":["when a business receives more cash than it spends in a period"]}', NULL, 'achieve positive cash flow / maintain positive cash flow', '[{"en":"The startup reached positive cash flow 18 months after launch.","zh-TW":"新創公司在推出18個月後實現了正現金流。"},{"en":"Positive cash flow gives a company the flexibility to invest and grow.","zh-TW":"正現金流使公司具有投資和增長的靈活性。"}]', NULL, NULL, 5, 5040, NULL),
(5041, 'positive working environment', '/ˈpɒzɪtɪv ˈwɜːrkɪŋ ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["積極的工作環境"],"en":["a supportive workplace culture that promotes employee wellbeing and productivity"]}', NULL, 'create a positive working environment / maintain a positive working environment', '[{"en":"A positive working environment reduces absenteeism and improves morale.","zh-TW":"積極的工作環境降低了缺勤率並提升了士氣。"},{"en":"HR initiatives aim to foster a positive working environment for all staff.","zh-TW":"人力資源計劃旨在為所有員工培養積極的工作環境。"}]', NULL, NULL, 5, 5041, NULL),
(5042, 'positivism', '/ˈpɒzɪtɪvɪzəm/', 'noun', '{"zh-TW":["實證主義"],"en":["a philosophical approach claiming knowledge is based on verified observation"]}', NULL, 'logical positivism / scientific positivism / critique of positivism', '[{"en":"Positivism holds that knowledge must be empirically verifiable.","zh-TW":"實證主義認為知識必須是可以實證驗證的。"},{"en":"Social positivism attempts to apply the methods of natural science to society.","zh-TW":"社會實證主義試圖將自然科學方法應用於社會。"}]', '{"adjective":"positivist","adverb":"positivistically"}', NULL, 4, 5042, NULL),
(5043, 'possess', '/pəˈzɛs/', 'verb', '{"zh-TW":["擁有；具有"],"en":["to have or own"]}', '{"prefix":{"text":"pos-","meaning":"able"},"root":{"text":"sess","meaning":"sit (坐)"}}', 'possess skills / possess the right / legally possess', '[{"en":"She possesses excellent leadership skills.","zh-TW":"她具備出色的領導力。"},{"en":"You must possess a valid ID to enter.","zh-TW":"進入須持有效證件。"}]', '{"noun":"possession","adjective":"possessive"}', NULL, 3, 5043, NULL),
(5044, 'possible', '/ˈpɒsɪbəl/', 'adjective', '{"zh-TW":["可能的"],"en":["able to be done or achieved"]}', NULL, 'as soon as possible / if possible', '[{"en":"Please reply as soon as possible.","zh-TW":"請盡快回覆。"},{"en":"We will deliver by Friday if possible.","zh-TW":"如果可能的話，我們週五前交貨。"}]', '{"adjective":"possible","noun":"possibility","adverb":"possibly","adjective2":"impossible"}', NULL, 3, 5044, NULL),
(5045, 'post', '/poʊst/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】張貼；郵件","【次要意義-名詞】職位；職務；崗位","【次要意義-動詞】派駐；調派（到某地任職）","【次要意義-名詞】（軍隊）駐地；哨位"],"en":["[primary] to mail something; a letter or package","[secondary - noun] a job or position in an organization","[secondary - verb] to send someone to work in a particular place","[secondary - noun] a military station"]}', NULL, 'fill a post / apply for a post / post someone abroad / keep someone posted', '[{"en":"We are looking for candidates to fill the post of regional manager.","zh-TW":"我們正在尋找候選人填補地區經理的職位。"},{"en":"She was posted to the Tokyo office for a two-year assignment.","zh-TW":"她被派駐東京辦事處，執行為期兩年的任務。"},{"en":"Please keep me posted on any developments in the negotiation.","zh-TW":"請隨時讓我了解談判的最新進展。"}]', '{"noun":"posting"}', 'post = 「職位」（fill a post）和「派駐」（post someone to）是 TOEIC 人事管理文章的高頻用法，keep someone posted（隨時通知）也是常考片語。', 1, 5045, NULL),
(5046, 'post-colonial', '/ˌpəʊstˈkɒlənɪəl/', 'adjective', '{"zh-TW":["後殖民的"],"en":["relating to the period after the end of colonialism; examining its lasting effects"]}', NULL, 'post-colonial theory / post-colonial society / post-colonial analysis', '[{"en":"Post-colonial theory examines how colonial power relations persist after independence.","zh-TW":"後殖民理論研究殖民權力關係如何在獨立後持續存在。"},{"en":"Post-colonial literature often addresses identity, hybridity, and displacement.","zh-TW":"後殖民文學通常涉及身份、混雜性和流離失所。"}]', '{"noun":"post-colonialism","adverb":"post-colonially"}', NULL, 5, 5046, NULL),
(5047, 'post-merger integration', '/poʊst ˈmɜːrdʒər ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["合併後整合"],"en":["the process of combining two companies after a merger is completed"]}', NULL, 'manage post-merger integration / post-merger integration challenges', '[{"en":"Post-merger integration was the most difficult phase of the deal.","zh-TW":"合併後整合是交易中最困難的階段。"},{"en":"A dedicated team was formed to oversee post-merger integration.","zh-TW":"成立了一個專屬團隊負責監督合併後整合工作。"}]', '{"abbreviation":"PMI"}', NULL, 5, 5047, NULL),
(5048, 'post-mortem', '/ˈpoʊst ˈmɔːrtəm/', 'noun', '{"zh-TW":["事後檢討；復盤"],"en":["a review conducted after a project or incident to identify lessons"]}', NULL, 'conduct a post-mortem / post-mortem report / post-mortem analysis', '[{"en":"The post-mortem identified communication failures as a root cause.","zh-TW":"事後檢討將溝通失敗確定為根本原因。"},{"en":"Regular post-mortems help teams continuously improve their processes.","zh-TW":"定期復盤幫助團隊持續改進其流程。"}]', NULL, NULL, 4, 5048, NULL),
(5049, 'post-tax profit', '/poʊst tæks ˈprɒfɪt/', 'noun', '{"zh-TW":["稅後利潤"],"en":["profit remaining after income tax has been deducted"]}', NULL, 'calculate post-tax profit / report post-tax profit', '[{"en":"Post-tax profit attributable to shareholders was 8 million.","zh-TW":"歸屬股東的稅後利潤為800萬元。"},{"en":"The post-tax profit margin improved after the tax reform.","zh-TW":"稅後利潤率在稅制改革後有所改善。"}]', NULL, NULL, 5, 5049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5050, 'postdoctoral', '/''pəʊst ˈdɒktərəl/', 'adjective', '{"zh-TW":["博士後的"],"en":["relating to research or study done after completing a doctoral degree"]}', NULL, 'postdoctoral research / postdoctoral fellowship / postdoctoral position', '[{"en":"She accepted a postdoctoral fellowship at a leading research university.","zh-TW":"她接受了一所頂尖研究型大學的博士後研究獎學金。"},{"en":"Postdoctoral researchers often lead independent projects in their field.","zh-TW":"博士後研究人員通常在其領域領導獨立的項目。"}]', NULL, NULL, 4, 5050, NULL),
(5051, 'postgraduate', '/ˌpəʊstˈɡrædʒuɪt/', 'adjective', '{"zh-TW":["研究所的；研究生的"],"en":["relating to study done after a first degree"]}', NULL, 'postgraduate degree / postgraduate program', '[{"en":"She enrolled in a postgraduate program in public health.","zh-TW":"她報名了公共衛生研究所課程。"},{"en":"Postgraduate study often leads to specialized career opportunities.","zh-TW":"研究所學習往往帶來專業的職業機會。"}]', '{"noun":"postgraduate"}', NULL, 4, 5051, NULL),
(5052, 'posting', '/ˈpoʊstɪŋ/', 'noun', '{"zh-TW":["記帳；過帳"],"en":["the process of entering transactions into accounting records"]}', NULL, 'process postings / journal posting / accounting posting', '[{"en":"All postings are made to the general ledger daily.","zh-TW":"所有記帳每天記入總帳。"},{"en":"An incorrect posting caused a discrepancy in the month-end accounts.","zh-TW":"錯誤的記帳在月末帳目中造成了差異。"}]', '{"verb":"post","adjective":"posted"}', NULL, 3, 5052, NULL),
(5053, 'postoperative', '/ˌpəʊstˈɒpərətɪv/', 'adjective', '{"zh-TW":["術後的"],"en":["relating to the period following surgery"]}', NULL, 'postoperative care / postoperative recovery / postoperative complications', '[{"en":"Postoperative care is critical for preventing infection.","zh-TW":"術後護理對於預防感染至關重要。"},{"en":"The patient experienced minimal postoperative pain after the procedure.","zh-TW":"患者在手術後疼痛極少。"}]', '{"adverb":"postoperatively"}', NULL, 5, 5053, NULL),
(5054, 'postpone', '/poʊstˈpoʊn/', 'verb', '{"zh-TW":["延期；推遲"],"en":["to arrange for later than planned"]}', '{"prefix":{"text":"post-","meaning":"after (之後)"},"root":{"text":"pone","meaning":"put (放)"}}', 'postpone a meeting / postpone indefinitely', '[{"en":"The meeting has been postponed until Friday.","zh-TW":"會議已推遲到週五。"},{"en":"They decided to postpone the product launch.","zh-TW":"他們決定推遲產品發布。"}]', '{"noun":"postponement"}', NULL, 3, 5054, 707),
(5055, 'postulate', '/ˈpɒstʃʊleɪt/', 'verb', '{"zh-TW":["假設；假定"],"en":["to suggest or assume as a basis for reasoning or action"]}', NULL, 'postulate a theory / postulate a principle / postulate that', '[{"en":"He postulated that language shapes the way we perceive reality.","zh-TW":"他假設語言塑造了我們感知現實的方式。"},{"en":"The model postulates a linear relationship between the two variables.","zh-TW":"該模型假設兩個變量之間存在線性關係。"}]', '{"noun":"postulate","adjective":"postulated"}', NULL, 3, 5055, NULL),
(5056, 'potential', '/pəˈtenʃl/', 'noun', '{"zh-TW":["潛力；可能性","潛在的；可能的"],"en":["latent qualities that may be developed","possible; capable of becoming"]}', '{"root":{"text":"potent","meaning":"power (力量)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與潛在力量相關的，即「潛力」。"}', 'reach one''s potential / growth potential / potential risk; potential risk / potential customer / growth potential', '[{"en":"She has the potential to become a great leader.","zh-TW":"她有潛力成為偉大的領導者。"},{"en":"We must consider the potential risks.","zh-TW":"我們必須考慮潛在風險。"},{"en":"There are potential risks in this investment.","zh-TW":"這項投資有潛在風險。"},{"en":"The market has great growth potential.","zh-TW":"市場有很大的成長潛力。"}]', '{"adjective":"potential","adverb":"potentially","noun":"potential, potentiality"}', NULL, 3, 5056, 415),
(5057, 'pottery', '/ˈpɒtəri/', 'noun', '{"zh-TW":["陶器；陶藝"],"en":["objects made from baked clay"]}', '{"root":{"text":"pot","meaning":"pot (壺)"},"suffix":{"text":"-ery","meaning":"art/place of (技藝/場所)"},"logic":"製作壺器的技藝，即「陶藝」。"}', 'pottery class / pottery wheel', '[{"en":"She makes pottery as a hobby.","zh-TW":"她以製陶為嗜好。"},{"en":"Ancient pottery was found at the excavation site.","zh-TW":"挖掘現場發現了古代陶器。"}]', '{"noun":"potter"}', NULL, 3, 5057, NULL),
(5058, 'pour', '/pɔːr/', 'verb', '{"zh-TW":["倒；傾注","大量投入"],"en":["to flow or cause to flow","to invest heavily"]}', NULL, 'pour money into / pour resources into', '[{"en":"The company poured millions into R&D.","zh-TW":"公司投入數百萬於研發。"},{"en":"Orders have been pouring in since the launch.","zh-TW":"自發布以來訂單源源不斷。"}]', NULL, NULL, 1, 5058, NULL),
(5059, 'poverty', '/ˈpɒvərti/', 'noun', '{"zh-TW":["貧窮；貧困","貧窮"],"en":["the state of being very poor","the state of being poor"]}', NULL, 'poverty line / poverty rate / live in poverty; poverty level / reduce poverty', '[{"en":"The poverty rate has decreased.","zh-TW":"貧困率已下降。"},{"en":"Many families live below the poverty line.","zh-TW":"許多家庭生活在貧窮線以下。"},{"en":"Reducing poverty requires collective effort.","zh-TW":"減少貧困需要集體努力。"},{"en":"The poverty rate dropped by 3%.","zh-TW":"貧困率下降了3%。"}]', '{"adjective":"impoverished"}', NULL, 3, 5059, NULL),
(5060, 'power', '/ˈpaʊər/', 'noun', '{"zh-TW":["力量；權力；電力"],"en":["ability to act","authority","electricity"]}', NULL, 'purchasing power / power outage', '[{"en":"Consumer purchasing power has declined.","zh-TW":"消費者購買力下降了。"},{"en":"A power outage disrupted operations.","zh-TW":"停電影響了營運。"}]', '{"noun":"power","adjective":"powerful","adjective2":"powerless","verb":"empower"}', NULL, 2, 5060, NULL),
(5061, 'power of attorney', '/ˈpaʊər əv əˈtɜːrni/', 'noun', '{"zh-TW":["授權書；委任狀"],"en":["legal authority granted to someone to act on another''s behalf"]}', NULL, 'grant power of attorney / limited power of attorney', '[{"en":"She granted her son power of attorney to manage her finances.","zh-TW":"她授予她的兒子管理財務的授權書。"},{"en":"A power of attorney must be notarized to be legally valid.","zh-TW":"授權書必須公證才能具有法律效力。"}]', NULL, NULL, 5, 5061, NULL),
(5062, 'PPC', '/ˌpiː piː ˈsiː/', 'noun', '{"zh-TW":["按點擊付費廣告"],"en":["pay-per-click; a digital advertising model where advertisers pay per click"]}', NULL, 'PPC campaign / PPC advertising / manage PPC / PPC budget', '[{"en":"The PPC campaign drove targeted traffic to the product page.","zh-TW":"按點擊付費廣告活動為產品頁面帶來了定向流量。"},{"en":"Effective PPC management can yield a strong return on ad spend.","zh-TW":"有效的PPC管理可以產生強勁的廣告支出回報。"}]', '{"full form":"pay-per-click"}', NULL, 1, 5062, NULL),
(5063, 'practical', 'ˈpræktɪkəl', 'adjective', '{"zh-TW":["實際的；實用的","可行的"],"en":["relating to real situations","sensible and realistic"]}', NULL, 'practical experience/practical solution', '[{"en":"We need a practical approach.","zh-TW":"我們需要一個實際的方法。"}]', '{"noun":"practicality","adverb":"practically"}', NULL, 3, 5063, NULL),
(5064, 'practice', '/ˈpræktɪs/', 'noun', '{"zh-TW":["實踐；慣例"],"en":["the actual doing of something; a habitual way"]}', NULL, 'best practice / put into practice / standard practice', '[{"en":"This is standard practice in our industry.","zh-TW":"這是我們行業的標準做法。"},{"en":"We put the theory into practice.","zh-TW":"我們將理論付諸實踐。"}]', '{"verb":"practice, practise","adjective":"practical","adverb":"practically","noun":"practitioner"}', NULL, 3, 5064, 416),
(5065, 'practitioner', '/prækˈtɪʃənər/', 'noun', '{"zh-TW":["從業者；實踐者"],"en":["a person who practices a profession or occupation"]}', NULL, 'legal practitioner / HR practitioner / experienced practitioner', '[{"en":"The workshop was led by an experienced HR practitioner.","zh-TW":"研討會由一位有經驗的人力資源從業者主持。"},{"en":"Legal practitioners must comply with strict professional conduct rules.","zh-TW":"法律從業者必須遵守嚴格的職業操守規則。"}]', '{"noun":"practice"}', NULL, 4, 5065, NULL),
(5066, 'pragmatic', '/præɡˈmætɪk/', 'adjective', '{"zh-TW":["務實的；實用主義的"],"en":["dealing with things sensibly and realistically based on practical considerations"]}', NULL, 'pragmatic approach / pragmatic solution / pragmatic leader', '[{"en":"The negotiators took a pragmatic approach to reach a compromise.","zh-TW":"談判者採取了務實的方式以達成妥協。"},{"en":"A pragmatic leader focuses on what works rather than what is ideal.","zh-TW":"務實的領導者關注有效的方法，而非理想的方法。"}]', '{"adverb":"pragmatically","noun":"pragmatism"}', NULL, 3, 5066, NULL),
(5067, 'pragmatic approach', '/''præɡˈmætɪk əˌprəʊtʃ/', 'noun', '{"zh-TW":["務實方法；實際手段"],"en":["a practical and results-oriented method of solving problems"]}', NULL, 'take a pragmatic approach / advocate for pragmatic approach', '[{"en":"The management took a pragmatic approach to resolving the budget shortfall.","zh-TW":"管理層採取了務實方法來解決預算短缺問題。"},{"en":"A pragmatic approach focuses on what works rather than what is theoretically perfect.","zh-TW":"務實方法側重於什麼有效，而不是理論上什麼是完美的。"}]', NULL, NULL, 5, 5067, NULL),
(5068, 'pragmatism', '/ˈpræɡmətɪzəm/', 'noun', '{"zh-TW":["實用主義"],"en":["a practical approach to problems; the philosophy that ideas are evaluated by their practical effects"]}', NULL, 'embrace pragmatism / philosophical pragmatism / policy pragmatism', '[{"en":"His pragmatism helped the team find workable solutions quickly.","zh-TW":"他的實用主義幫助團隊迅速找到可行的解決方案。"},{"en":"Pragmatism values what works over what is theoretically ideal.","zh-TW":"實用主義重視有效的方法，而非理論上的理想。"}]', '{"adjective":"pragmatic","noun":"pragmatist"}', NULL, 4, 5068, NULL),
(5069, 'pre-approved', 'priː əˈpruːvd', 'adjective', '{"zh-TW":["預先批准的；事先獲批的","已審核的"],"en":["approved in advance","already agreed to"]}', NULL, 'pre-approved budget/pre-approved vendor', '[{"en":"Use pre-approved suppliers only.","zh-TW":"請只使用預先批准的供應商。"}]', NULL, NULL, 4, 5069, NULL),
(5070, 'pre-existing condition', '/priː ɪɡˈzɪstɪŋ kənˈdɪʃən/', 'noun', '{"zh-TW":["既往症；預先存在的疾病"],"en":["a health condition that existed before insurance enrollment"]}', NULL, 'pre-existing condition exclusion / cover pre-existing conditions', '[{"en":"Some insurance plans exclude pre-existing conditions.","zh-TW":"一些保險計劃不承保既往症。"},{"en":"Under current law, insurers cannot deny coverage for pre-existing conditions.","zh-TW":"依現行法律，保險公司不得以既往症為由拒絕承保。"}]', NULL, NULL, 5, 5070, NULL),
(5071, 'pre-tax profit', '/priː tæks ˈprɒfɪt/', 'noun', '{"zh-TW":["稅前利潤"],"en":["profit before income tax has been deducted"]}', NULL, 'report pre-tax profit / pre-tax profit margin', '[{"en":"The company reported pre-tax profit of 15 million dollars.","zh-TW":"公司報告了1500萬美元的稅前利潤。"},{"en":"Pre-tax profit grew despite higher raw material costs.","zh-TW":"儘管原材料成本較高，稅前利潤仍然增長了。"}]', NULL, NULL, 5, 5071, NULL),
(5072, 'precariat', '/prɪˈkeəriæt/', 'noun', '{"zh-TW":["不穩定無產者；臨時工群體"],"en":["a social class of people living with low income and little job security"]}', NULL, 'growing precariat / precariat workers / precariat in gig economy', '[{"en":"The gig economy has created a large precariat without benefits or job security.","zh-TW":"零工經濟創造了大量沒有福利或工作保障的不穩定無產者。"},{"en":"The precariat is particularly vulnerable to economic shocks.","zh-TW":"不穩定無產者對經濟衝擊特別脆弱。"}]', NULL, NULL, 3, 5072, NULL),
(5073, 'precarious', '/''prɪˈkeəriəs/', 'adjective', '{"zh-TW":["不穩定的；危險的"],"en":["not securely held or in position; dependent on chance; uncertain"]}', NULL, 'precarious situation / precarious balance / precarious position', '[{"en":"The startup was in a precarious financial position after losing its main investor.","zh-TW":"在失去主要投資者後，這家新創公司處於不穩定的財務狀況。"},{"en":"The worker balanced precariously on the scaffolding during the construction.","zh-TW":"工人在施工期間危險地站在腳手架上保持平衡。"}]', '{"adverb":"precariously","noun":"precariousness"}', NULL, 4, 5073, NULL),
(5074, 'precaution', '/prɪˈkɔːʃən/', 'noun', '{"zh-TW":["預防措施"],"en":["an action taken to prevent something bad"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"caution","meaning":"warning (警告)"}}', 'take precautions / safety precaution / as a precaution', '[{"en":"We take every precaution to ensure safety.","zh-TW":"我們採取一切預防措施確保安全。"},{"en":"As a precaution, please back up your files.","zh-TW":"作為預防，請備份文件。"}]', '{"adjective":"precautionary"}', NULL, 4, 5074, NULL),
(5075, 'precautionary', '/''prɪˌkɔːʃəneri/', 'adjective', '{"zh-TW":["預防性的；謹慎的"],"en":["carried out as a precaution to avoid possible danger, harm, or negative outcomes"]}', NULL, 'precautionary measures / precautionary principle / precautionary step', '[{"en":"The government took precautionary measures to prevent the spread of the disease.","zh-TW":"政府採取了預防措施，以防止疾病傳播。"},{"en":"As a precautionary step, the facility was evacuated pending a safety inspection.","zh-TW":"作為預防措施，設施在安全檢查前進行了疏散。"}]', '{"noun":"precaution","adverb":"precautionarily"}', NULL, 5, 5075, NULL),
(5076, 'precede', '/prɪˈsiːd/', 'verb', '{"zh-TW":["在...之前"],"en":["to come before in time or order"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cede","meaning":"go (走)"}}', 'precede sth. / preceding year / as preceded by', '[{"en":"A brief introduction preceded the main speech.","zh-TW":"簡短介紹在主要演講之前。"},{"en":"In the preceding quarter, sales were strong.","zh-TW":"在前一季度，銷售強勁。"}]', '{"adjective":"preceding, precedent","noun":"precedent, precedence"}', NULL, 3, 5076, NULL),
(5077, 'precedent', '/ˈprɛsɪdənt/', 'noun', '{"zh-TW":["先例"],"en":["an earlier event or action used as an example"]}', NULL, 'set a precedent / legal precedent', '[{"en":"This case sets an important precedent.","zh-TW":"這個案件開創了重要的先例。"},{"en":"There is no precedent for this situation.","zh-TW":"這種情況沒有先例可循。"}]', '{"adjective":"unprecedented"}', NULL, 3, 5077, NULL),
(5078, 'precipitation', '/prɪˌsɪpɪˈteɪʃn/', 'noun', '{"zh-TW":["降水"],"en":["rain, snow, sleet, or hail that falls to the ground"]}', '{"prefix":{"text":"pre-","meaning":"before (前)"},"root":{"text":"cipit","meaning":"head/fall (頭/落下)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"頭朝下落下的過程，即「降水」。"}', 'annual precipitation / heavy precipitation', '[{"en":"The annual precipitation in this area is 1200mm.","zh-TW":"這個地區年降水量為1200毫米。"},{"en":"Heavy precipitation is expected overnight.","zh-TW":"預計夜間會有大量降水。"}]', '{"verb":"precipitate"}', NULL, 5, 5078, NULL),
(5079, 'precipitous', '/''prɪˈsɪpɪtəs/', 'adjective', '{"zh-TW":["陡峭的；急劇的；輕率的"],"en":["dangerously high or steep; done suddenly and without careful consideration"]}', NULL, 'precipitous decline / precipitous drop / precipitous rise', '[{"en":"The stock market experienced a precipitous drop after the announcement.","zh-TW":"公告發布後，股市出現了急劇下跌。"},{"en":"The company made a precipitous decision to expand without proper planning.","zh-TW":"公司在沒有適當規劃的情況下做出了輕率的擴張決定。"}]', '{"adverb":"precipitously","noun":"precipice"}', NULL, 4, 5079, NULL),
(5080, 'precise', '/prɪˈsaɪs/', 'adjective', '{"zh-TW":["精確的；準確的"],"en":["exact and accurate"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"cise","meaning":"cut (切)"}}', 'precise measurement / to be precise / precise instructions', '[{"en":"Please give me the precise figures.","zh-TW":"請給我精確數據。"},{"en":"To be precise, the total is $45,231.","zh-TW":"準確地說，總數是$45,231。"}]', '{"adverb":"precisely","noun":"precision"}', NULL, 3, 5080, NULL),
(5081, 'preclude', '/prɪˈkluːd/', 'verb', '{"zh-TW":["排除；阻止"],"en":["to prevent something from happening; to make impossible"]}', NULL, 'preclude the possibility / preclude participation / preclude action', '[{"en":"The regulatory framework precludes certain investment activities.","zh-TW":"監管框架排除了某些投資活動的可能性。"},{"en":"Poor data quality precludes drawing firm conclusions.","zh-TW":"數據品質差排除了得出確定結論的可能性。"}]', '{"noun":"preclusion","adjective":"preclusive"}', NULL, 3, 5081, NULL),
(5082, 'predatory pricing', '/ˈpredətəri ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["掠奪性定價"],"en":["setting prices artificially low to drive competitors out of the market"]}', NULL, 'engage in predatory pricing / predatory pricing investigation', '[{"en":"Regulators investigated the company for predatory pricing practices.","zh-TW":"監管機構調查了公司的掠奪性定價行為。"},{"en":"Predatory pricing is illegal in many jurisdictions.","zh-TW":"掠奪性定價在許多司法管轄區是非法的。"}]', NULL, NULL, 5, 5082, NULL),
(5083, 'predecessor', '/ˈpredəsesər/', 'noun', '{"zh-TW":["前任；前身"],"en":["a person or thing that came before another in a role or position"]}', NULL, 'my predecessor / predecessor company / predecessor system', '[{"en":"She inherited a well-run team from her predecessor.","zh-TW":"她從前任那裡繼承了一支管理有序的團隊。"},{"en":"The new system replaced the predecessor which was installed in 2010.","zh-TW":"新系統取代了2010年安裝的前身系統。"}]', '{"opposite":"successor"}', NULL, 4, 5083, NULL),
(5084, 'predict', '/prɪˈdɪkt/', 'verb', '{"zh-TW":["預測","預測；預言"],"en":["to say what will happen in the future"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"dict","meaning":"say (說)"},"logic":"事先說出，即「預測」。"}', 'predict the outcome / predict the future / hard to predict; predict the outcome / predict growth / as predicted', '[{"en":"Experts predict the economy will grow next year.","zh-TW":"專家預測明年經濟將成長。"},{"en":"It''s difficult to predict the weather accurately.","zh-TW":"精準預測天氣很困難。"},{"en":"Analysts predict strong growth next quarter.","zh-TW":"分析師預測下季度強勁增長。"},{"en":"It is difficult to predict market trends.","zh-TW":"很難預測市場趨勢。"}]', '{"noun":"prediction","adjective":"predictable","adverb":"predictably"}', NULL, 3, 5084, NULL),
(5085, 'predictive analytics', '/prɪˈdɪktɪv ˌænəˈlɪtɪks/', 'noun', '{"zh-TW":["預測分析"],"en":["the use of data and algorithms to forecast future events"]}', NULL, 'apply predictive analytics / predictive analytics model / predictive analytics tools', '[{"en":"Predictive analytics helps retailers forecast demand and optimize inventory.","zh-TW":"預測分析幫助零售商預測需求並優化庫存。"},{"en":"Healthcare uses predictive analytics to identify at-risk patients before crises occur.","zh-TW":"醫療保健使用預測分析在危機發生前識別高風險患者。"}]', NULL, NULL, 5, 5085, NULL),
(5086, 'predominant', '/prɪˈdɒmɪnənt/', 'adjective', '{"zh-TW":["主要的；佔優勢的"],"en":["most common or most powerful"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"domin","meaning":"rule (統治)"},"suffix":{"text":"-ant","meaning":"...的"}}', 'predominant factor / predominant view', '[{"en":"Cost is the predominant factor in their decision.","zh-TW":"成本是他們決定的主要因素。"},{"en":"English is the predominant language in business.","zh-TW":"英語是商務中的主要語言。"}]', '{"adverb":"predominantly","verb":"predominate"}', NULL, 4, 5086, NULL),
(5087, 'predominantly', '/''prɪˈdɒmɪnəntli/', 'adverb', '{"zh-TW":["主要地；占主導地位地"],"en":["mainly; for the most part"]}', NULL, 'predominantly female / predominantly used / predominantly driven', '[{"en":"The company''s revenue is predominantly generated from subscription services.","zh-TW":"公司的收入主要來自訂閱服務。"},{"en":"The workforce is predominantly composed of engineering graduates.","zh-TW":"工作人員主要由工程學畢業生組成。"}]', '{"adjective":"predominant","verb":"predominate"}', NULL, 5, 5087, NULL),
(5088, 'preemptive', '/''priːˈemptɪv/', 'adjective', '{"zh-TW":["先發制人的；預防性的"],"en":["taken as a measure against something anticipated; serving to preempt"]}', NULL, 'preemptive action / preemptive strike / preemptive measure', '[{"en":"The company took preemptive action to address potential supply chain weaknesses.","zh-TW":"公司採取了先發制人的行動，解決潛在的供應鏈弱點。"},{"en":"A preemptive response to customer complaints prevents negative reviews from spreading.","zh-TW":"對客戶投訴的預防性回應可防止負面評論的擴散。"}]', '{"adverb":"preemptively"}', NULL, 4, 5088, NULL),
(5089, 'prefer', '/prɪˈfɜːr/', 'verb', '{"zh-TW":["偏好；更喜歡"],"en":["to like one thing more than another"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'prefer A to B / prefer to do', '[{"en":"Most clients prefer email communication.","zh-TW":"多數客戶偏好電郵溝通。"},{"en":"I prefer to work from home on Fridays.","zh-TW":"我偏好週五在家工作。"}]', '{"noun":"preference","adjective":"preferable, preferred","adverb":"preferably"}', NULL, 2, 5089, NULL),
(5090, 'preferential rate', '/ˌprefəˈrenʃəl reɪt/', 'noun', '{"zh-TW":["優惠利率；優惠費率"],"en":["a below-standard rate offered to preferred customers or under special conditions"]}', NULL, 'negotiate a preferential rate / preferential rate agreement', '[{"en":"Long-standing clients received a preferential rate on all currency transactions.","zh-TW":"長期客戶在所有貨幣交易中獲得了優惠利率。"},{"en":"A preferential rate is used to incentivize early commitment or loyalty.","zh-TW":"優惠費率用於激勵早期承諾或忠誠度。"}]', NULL, NULL, 5, 5090, NULL),
(5091, 'preferred provider', '/prɪˈfɜːrd prəˈvaɪdər/', 'noun', '{"zh-TW":["優先供應商；指定供應商"],"en":["a supplier given priority status due to quality, price, or relationship"]}', NULL, 'designate a preferred provider / preferred provider agreement', '[{"en":"Travel bookings must be made through the preferred provider.","zh-TW":"差旅預訂必須通過優先供應商進行。"},{"en":"The preferred provider agreement offered discounted rates for bulk orders.","zh-TW":"優先供應商協議為大量訂購提供了折扣費率。"}]', NULL, NULL, 5, 5091, NULL),
(5092, 'preferred shares', '/prɪˈfɜːrd ʃeərz/', 'noun', '{"zh-TW":["優先股"],"en":["a class of shares that give holders priority over common shareholders for dividends"]}', NULL, 'issue preferred shares / preferred shares dividend', '[{"en":"Investors bought preferred shares for the guaranteed dividend yield.","zh-TW":"投資者購買優先股以獲得有保障的股息殖利率。"},{"en":"Preferred shares do not typically carry voting rights.","zh-TW":"優先股通常不附帶投票權。"}]', '{"opposite":"common shares"}', NULL, 5, 5092, NULL),
(5093, 'preferred stock', '/prɪˈfɜːrd stɒk/', 'noun', '{"zh-TW":["優先股"],"en":["shares that give holders priority for dividends and assets over common stockholders"]}', NULL, 'issue preferred stock / hold preferred stock', '[{"en":"The investor received preferred stock with a guaranteed 6% dividend.","zh-TW":"投資者獲得了保證6%股息的優先股。"},{"en":"Preferred stock holders take priority in the event of liquidation.","zh-TW":"在清算時，優先股持有人享有優先權。"}]', '{"opposite":"common stock"}', NULL, 5, 5093, NULL),
(5094, 'preliminary', '/prɪˈlɪmɪneri/', 'adjective', '{"zh-TW":["初步的；預備的"],"en":["coming before the main part"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"limin","meaning":"threshold (門檻)"}}', 'preliminary results / preliminary investigation', '[{"en":"Preliminary results indicate success.","zh-TW":"初步結果顯示成功。"},{"en":"A preliminary review was conducted.","zh-TW":"進行了初步審查。"}]', '{"noun":"preliminary"}', NULL, 4, 5094, 418),
(5095, 'preliminary agreement', '/prɪˈlɪmɪnəri əˈɡriːmənt/', 'noun', '{"zh-TW":["初步協議"],"en":["an agreement in principle before detailed terms are finalized"]}', NULL, 'sign a preliminary agreement / preliminary agreement discussions', '[{"en":"A preliminary agreement was signed to secure the exclusive negotiation period.","zh-TW":"簽署了初步協議以確保獨家談判期間。"},{"en":"The preliminary agreement outlined the key commercial terms.","zh-TW":"初步協議概述了主要商業條款。"}]', NULL, NULL, 5, 5095, NULL),
(5096, 'premiere', '/prɪˈmɪər/', 'noun', '{"zh-TW":["首映；首演"],"en":["the first public showing of a movie or performance"]}', '{"prefix":{"text":"pre-","meaning":"first (第一)"},"root":{"text":"miere","meaning":"first (最初)"},"logic":"最初的公開展演，即「首映」。"}', 'movie premiere / world premiere', '[{"en":"The movie premiere attracted many celebrities.","zh-TW":"電影首映吸引了許多名人。"},{"en":"The play had its world premiere in London.","zh-TW":"這齣戲在倫敦舉行了世界首演。"}]', '{"verb":"premiere"}', NULL, 3, 5096, NULL),
(5097, 'premise', '/ˈprɛmɪs/', 'noun', '{"zh-TW":["前提","場所"],"en":["a statement assumed to be true","a building and its land"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"mis","meaning":"send (送)"}}', 'on the premise that / business premises', '[{"en":"The plan is based on the premise that sales will grow.","zh-TW":"計劃以銷售將增長為前提。"},{"en":"Smoking is not allowed on the premises.","zh-TW":"場所內禁止吸煙。"}]', NULL, NULL, 3, 5097, NULL),
(5098, 'premises', '/ˈpremɪsɪz/', 'noun', '{"zh-TW":["房舍；場地"],"en":["a building and the land it occupies, especially when used for business"]}', NULL, 'business premises / vacate the premises / on the premises', '[{"en":"All visitors must sign in before entering the premises.","zh-TW":"所有訪客在進入場地前必須登記。"},{"en":"The company relocated to larger premises downtown.","zh-TW":"公司搬遷到市中心更大的辦公場所。"}]', NULL, NULL, 3, 5098, NULL),
(5099, 'premium', '/ˈpriːmiəm/', 'noun', '{"zh-TW":["保費","額外費用","優質的"],"en":["an insurance payment","an extra charge","of high quality"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"em","meaning":"buy (買)"}}', 'insurance premium / premium quality / at a premium', '[{"en":"Insurance premiums have increased this year.","zh-TW":"今年保費增加了。"},{"en":"Office space is available at a premium.","zh-TW":"辦公空間以高價提供。"}]', NULL, NULL, 3, 5099, 419);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5100, 'premium pricing', '/ˈpriːmiəm ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["溢價定價；高端定價"],"en":["setting a higher price to signal superior quality or exclusivity"]}', NULL, 'adopt premium pricing / premium pricing strategy', '[{"en":"The luxury brand maintains premium pricing to reinforce exclusivity.","zh-TW":"奢侈品品牌維持溢價定價以強化排他性。"},{"en":"Premium pricing is only sustainable if the product delivers exceptional quality.","zh-TW":"只有產品提供卓越品質，溢價定價才是可持續的。"}]', NULL, NULL, 5, 5100, NULL),
(5101, 'premium waiver', '/ˈpriːmiəm ˈweɪvər/', 'noun', '{"zh-TW":["保費豁免"],"en":["a provision excusing the insured from paying premiums under certain conditions"]}', NULL, 'premium waiver benefit / claim premium waiver', '[{"en":"The premium waiver kicks in if the policyholder becomes disabled.","zh-TW":"如果保單持有人殘疾，保費豁免條款即生效。"},{"en":"A premium waiver rider was added to the life insurance policy.","zh-TW":"人壽保險保單添加了保費豁免附加條款。"}]', NULL, NULL, 5, 5101, NULL),
(5102, 'prepaid expense', '/ˌpriːpeɪd ɪkˈspens/', 'noun', '{"zh-TW":["預付費用"],"en":["a payment made in advance for goods or services to be received later"]}', NULL, 'record prepaid expenses / prepaid expense account / amortize prepaid expenses', '[{"en":"Insurance premiums paid upfront are recorded as prepaid expenses.","zh-TW":"預先支付的保險費記錄為預付費用。"},{"en":"Prepaid expenses are classified as current assets on the balance sheet.","zh-TW":"預付費用在資產負債表上被列為流動資產。"}]', NULL, NULL, 5, 5102, NULL),
(5103, 'preparation', '/ˌprɛpəˈreɪʃən/', 'noun', '{"zh-TW":["準備；籌備"],"en":["the process of getting ready"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"par","meaning":"make ready (準備)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'in preparation for / make preparations', '[{"en":"The team is making preparations for the launch.","zh-TW":"團隊正在為發布做準備。"},{"en":"In preparation for the audit, please organize files.","zh-TW":"為準備審計，請整理文件。"}]', '{"verb":"prepare","adjective":"preparatory"}', NULL, 4, 5103, 606),
(5104, 'prepare', '/prɪˈpɛr/', 'verb', '{"zh-TW":["準備"],"en":["to make ready for use or an event"]}', NULL, 'prepare for / well-prepared', '[{"en":"Please prepare the report by Monday.","zh-TW":"請在週一前準備好報告。"},{"en":"We are well-prepared for the audit.","zh-TW":"我們為審計做了充分準備。"}]', '{"verb":"prepare","noun":"preparation","adjective":"prepared"}', NULL, 3, 5104, NULL),
(5105, 'prepayment', '/ˈpriːpeɪmənt/', 'noun', '{"zh-TW":["預付款"],"en":["payment made in advance before goods or services are received"]}', NULL, 'require a prepayment / apply for a prepayment', '[{"en":"A 30% prepayment is required to confirm the order.","zh-TW":"確認訂單需要30%的預付款。"},{"en":"Prepayment reduces default risk for suppliers.","zh-TW":"預付款降低了供應商的違約風險。"}]', '{"verb":"prepay","adjective":"prepaid"}', NULL, 4, 5105, NULL),
(5106, 'prerequisite', '/ˌpriːˈrɛkwɪzɪt/', 'noun', '{"zh-TW":["先修課程；先決條件"],"en":["a course or condition required before taking another"]}', NULL, 'prerequisite course / fulfill prerequisites', '[{"en":"Introduction to Chemistry is a prerequisite for this course.","zh-TW":"化學入門是這門課的先修課程。"},{"en":"Students must meet the prerequisites before enrolling.","zh-TW":"學生在報名前必須滿足先決條件。"}]', '{"adjective":"prerequisite"}', NULL, 4, 5106, NULL),
(5107, 'prescribe', '/prɪˈskraɪb/', 'verb', '{"zh-TW":["規定；指示"],"en":["to state officially what should be done"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"scribe","meaning":"write (寫)"}}', 'prescribed by law / prescribed procedures', '[{"en":"The law prescribes strict penalties.","zh-TW":"法律規定了嚴格的處罰。"},{"en":"Follow the prescribed procedures.","zh-TW":"遵循規定的程序。"}]', '{"noun":"prescription","adjective":"prescribed"}', NULL, 3, 5107, NULL),
(5108, 'prescription', '/prɪˈskrɪpʃən/', 'noun', '{"zh-TW":["處方；藥方"],"en":["an instruction from a doctor to a pharmacist"]}', NULL, 'write a prescription / fill a prescription', '[{"en":"The doctor wrote a prescription for antibiotics.","zh-TW":"醫生開了抗生素的處方。"},{"en":"Take the prescription to the pharmacy to get your medicine.","zh-TW":"將處方帶到藥局領取您的藥物。"}]', '{"verb":"prescribe","adjective":"prescribed"}', NULL, 4, 5108, NULL),
(5109, 'prescription drug', '/prɪˈskrɪpʃən drʌɡ/', 'noun', '{"zh-TW":["處方藥"],"en":["a medicine that requires a doctor''s prescription"]}', NULL, 'fill a prescription drug / prescription drug coverage', '[{"en":"Prescription drugs are covered under the health plan.","zh-TW":"處方藥在健康計劃下獲得承保。"},{"en":"Some prescription drugs are only available at hospital pharmacies.","zh-TW":"某些處方藥只在醫院藥局供應。"}]', NULL, NULL, 5, 5109, NULL),
(5110, 'presence', '/ˈprɛzəns/', 'noun', '{"zh-TW":["存在；出席","風範"],"en":["the state of being present","a person''s bearing"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sens","meaning":"be (存在)"}}', 'in the presence of / online presence / market presence', '[{"en":"The company has a strong online presence.","zh-TW":"公司有強大的線上存在感。"},{"en":"Your presence at the meeting is required.","zh-TW":"你需出席會議。"}]', '{"adjective":"present","verb":"present"}', NULL, 3, 5110, NULL),
(5111, 'present', '/prɪˈzɛnt/', 'verb', '{"zh-TW":["【主要意義-名詞】禮物；現在","【次要意義-形容詞】目前在場的；出席的","【次要意義-動詞】呈現；提出；引起（困難）"],"en":["[primary - noun] a gift; the current time","[secondary - adjective] being in a place; existing now","[secondary - verb] to show, give, or cause something"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sent","meaning":"be (存在)"}}', 'present a challenge / present findings / those present / present oneself', '[{"en":"The new regulation presents a significant challenge for small businesses.","zh-TW":"新法規對小型企業構成重大挑戰。"},{"en":"All staff members present at the meeting must sign the attendance sheet.","zh-TW":"所有出席會議的員工必須在出席單上簽名。"},{"en":"The auditor presented the financial findings to the board of directors.","zh-TW":"審計師向董事會提交了財務調查結果。"}]', '{"noun":"presentation, presenter","adverb":"presently"}', 'present 重音在第二音節時為動詞，表「提交/呈現/引起」；片語 present a challenge（構成挑戰）是 TOEIC 高頻句型，present 作形容詞「在場的」也常考。', 3, 5111, NULL),
(5112, 'present value', '/ˈprezənt ˈvæljuː/', 'noun', '{"zh-TW":["現值"],"en":["the current worth of a future sum of money, discounted at a given rate"]}', NULL, 'calculate present value / determine present value', '[{"en":"The present value of the future cash flows was 10 million.","zh-TW":"未來現金流的現值為1000萬元。"},{"en":"Present value calculations are essential in investment decision-making.","zh-TW":"現值計算在投資決策中至關重要。"}]', NULL, NULL, 5, 5112, NULL),
(5113, 'presentation', '/ˌprezənˈteɪʃən/', 'noun', '{"zh-TW":["簡報；演示"],"en":["a formal talk or demonstration to an audience, often with visual aids"]}', NULL, 'deliver a presentation / board presentation / sales presentation', '[{"en":"She gave an impressive presentation to the executive committee.","zh-TW":"她向執行委員會做了令人印象深刻的簡報。"},{"en":"The presentation covered the company''s five-year growth strategy.","zh-TW":"簡報涵蓋了公司的五年增長策略。"}]', '{"verb":"present","noun":"presenter"}', NULL, 4, 5113, 177),
(5114, 'preserve', '/prɪˈzɜːrv/', 'verb', '{"zh-TW":["保存；維護"],"en":["to keep in its original state","to keep safe or maintain"]}', '{"prefix":{"text":"pre-","meaning":"before (預先)"},"root":{"text":"serve","meaning":"keep (保持)"},"logic":"預先保持好，即「保存」。"}', 'preserve wildlife / preserve tradition / well-preserved; preserve the environment / preserve quality', '[{"en":"We must preserve our natural resources.","zh-TW":"我們必須保存自然資源。"},{"en":"The old building has been well preserved.","zh-TW":"這棟老建築保存得很好。"},{"en":"We must preserve the quality of our products.","zh-TW":"我們必須維護產品品質。"},{"en":"Efforts to preserve the environment are ongoing.","zh-TW":"保護環境的努力仍在進行。"}]', '{"noun":"preservation"}', NULL, 3, 5114, NULL),
(5115, 'preside', '/prɪˈzaɪd/', 'verb', '{"zh-TW":["主持；主管"],"en":["to be in charge of a meeting"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"side","meaning":"sit (坐)"}}', 'preside over / preside at a meeting', '[{"en":"The chairman presided over the meeting.","zh-TW":"主席主持了會議。"},{"en":"She presides over a team of 50.","zh-TW":"她管理50人的團隊。"}]', '{"noun":"president, presidency","adjective":"presidential"}', NULL, 3, 5115, NULL),
(5116, 'press', '/prɛs/', 'verb', '{"zh-TW":["【主要意義-動詞】按壓；擠壓","【次要意義-名詞】新聞界；媒體","【次要意義-動詞】催促；施壓","【次要意義-動詞/名詞】熨燙；熨斗"],"en":["[primary] to push firmly against something","[secondary - noun] newspapers and journalists collectively","[secondary - verb] to urge someone to do something","[secondary - verb/noun] to iron clothes; the act of ironing"]}', NULL, 'press conference / press release / press for a decision / a good press', '[{"en":"The company issued a press release announcing the merger.","zh-TW":"公司發布了一份宣布合並的新聞稿。"},{"en":"The union has been pressing management for a wage increase.","zh-TW":"工會一直在向管理層施壓要求加薪。"},{"en":"The new product received a good press from industry journalists.","zh-TW":"新產品獲得了業界記者的好評。"}]', '{"noun":"pressure, pressing","adjective":"pressing"}', 'press 作名詞意為「新聞界」（press release = 新聞稿），動詞 press for = 施壓要求，TOEIC 媒體或公關文章必考詞彙，press conference（記者招待會）也是高頻搭配。', 2, 5116, NULL),
(5117, 'press conference', '/''pres ˌkɒnfərəns/', 'noun', '{"zh-TW":["記者招待會；新聞發布會"],"en":["a meeting where a person makes a statement to the media and reporters ask questions"]}', NULL, 'hold a press conference / attend a press conference / announce at a press conference', '[{"en":"The CEO held a press conference to address the product recall.","zh-TW":"首席執行官召開了記者招待會，處理產品召回事宜。"},{"en":"The prime minister scheduled a press conference to announce the new policy.","zh-TW":"總理安排了一個新聞發布會來宣布新政策。"}]', NULL, NULL, 5, 5117, NULL),
(5118, 'press release', '/pres rɪˈliːs/', 'noun', '{"zh-TW":["新聞稿"],"en":["an official statement issued to media organizations"]}', NULL, 'issue a press release / write a press release / press release distribution', '[{"en":"The company issued a press release announcing the new product launch.","zh-TW":"公司發布了宣布新產品上市的新聞稿。"},{"en":"A well-crafted press release can generate significant media coverage.","zh-TW":"一份精心撰寫的新聞稿可以產生重大的媒體報導。"}]', '{"verb":"issue a press release"}', NULL, 5, 5118, NULL),
(5119, 'pressure', '/ˈprɛʃər/', 'noun', '{"zh-TW":["壓力"],"en":["the force exerted; stress"]}', '{"root":{"text":"press","meaning":"push (推)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'under pressure / put pressure on / peer pressure', '[{"en":"The team is under pressure to meet deadlines.","zh-TW":"團隊有趕截止日期的壓力。"},{"en":"Don''t put too much pressure on yourself.","zh-TW":"別給自己太大壓力。"}]', '{"verb":"pressure, pressurize"}', NULL, 3, 5119, NULL),
(5120, 'presume', '/prɪˈzjuːm/', 'verb', '{"zh-TW":["假定；推測"],"en":["to suppose; to assume"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"sume","meaning":"take (拿)"}}', 'presume that / be presumed to / presumably', '[{"en":"I presume you have read the report.","zh-TW":"我假定你已讀了報告。"},{"en":"He is presumed to be responsible.","zh-TW":"他被認為應負責。"}]', '{"noun":"presumption","adjective":"presumptuous","adverb":"presumably"}', NULL, 3, 5120, NULL),
(5121, 'presuppose', '/''priːsəˌpəʊz/', 'verb', '{"zh-TW":["預設；假設"],"en":["to require something as a prior condition; to take for granted"]}', NULL, 'presuppose knowledge / presuppose agreement / wrongly presuppose', '[{"en":"The question presupposes that all employees have access to the same resources.","zh-TW":"這個問題預設了所有員工都能獲得相同的資源。"},{"en":"It is dangerous to presuppose that past success guarantees future performance.","zh-TW":"假設過去的成功保證未來的表現是危險的。"}]', '{"noun":"presupposition","adjective":"presupposed"}', NULL, 4, 5121, NULL),
(5122, 'pretty', '/ˈprɪti/', 'adverb', '{"zh-TW":["相當；漂亮的"],"en":["to a moderately high degree","attractive"]}', NULL, 'pretty good / pretty much', '[{"en":"The results are pretty good.","zh-TW":"結果相當不錯。"},{"en":"We are pretty much done.","zh-TW":"我們差不多完成了。"}]', '{"adjective":"pretty","adverb":"pretty"}', NULL, 2, 5122, NULL),
(5123, 'prevail', '/prɪˈveɪl/', 'verb', '{"zh-TW":["盛行；獲勝"],"en":["to be widespread; to win"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vail","meaning":"be strong (強大)"}}', 'prevailing conditions / prevail upon / justice prevails', '[{"en":"Common sense prevailed in the end.","zh-TW":"最終常識佔了上風。"},{"en":"Such attitudes still prevail in some companies.","zh-TW":"這種態度在一些公司仍盛行。"}]', '{"adjective":"prevailing, prevalent","noun":"prevalence"}', NULL, 3, 5123, NULL),
(5124, 'prevalent', '/''prevələnt/', 'adjective', '{"zh-TW":["普遍的；盛行的"],"en":["widespread in a particular area or at a particular time"]}', NULL, 'prevalent issue / widely prevalent / prevalent trend', '[{"en":"Remote working has become increasingly prevalent in recent years.","zh-TW":"近年來，遠程工作變得越來越普遍。"},{"en":"A prevalent misconception is that cutting costs always reduces quality.","zh-TW":"一個普遍的誤解是降低成本總是會降低質量。"}]', '{"adverb":"prevalently","noun":"prevalence"}', NULL, 3, 5124, NULL),
(5125, 'prevent', '/prɪˈvent/', 'verb', '{"zh-TW":["預防；阻止","防止；阻止"],"en":["to stop something from happening"]}', '{"prefix":{"text":"pre-","meaning":"before (在前)"},"root":{"text":"vent","meaning":"come (來)"},"logic":"在某事來臨前阻止，即「預防」。"}', 'prevent accidents / prevent disease / prevent from; prevent sth. from happening / prevent damage', '[{"en":"Regular exercise helps prevent heart disease.","zh-TW":"規律運動有助預防心臟病。"},{"en":"The barrier prevents people from falling.","zh-TW":"護欄防止人跌落。"},{"en":"We must prevent this from happening again.","zh-TW":"我們必須防止這再次發生。"},{"en":"Regular maintenance prevents costly repairs.","zh-TW":"定期維護防止昂貴的維修。"}]', '{"noun":"prevention","adjective":"preventive"}', NULL, 3, 5125, NULL),
(5126, 'preventive action', '/prɪˈventɪv ˈækʃən/', 'noun', '{"zh-TW":["預防措施"],"en":["a step taken to prevent a potential problem before it occurs"]}', NULL, 'implement preventive action / preventive action plan', '[{"en":"Preventive action was taken after identifying a potential system vulnerability.","zh-TW":"在識別出潛在系統漏洞後採取了預防措施。"},{"en":"CAPA combines corrective and preventive action to improve quality.","zh-TW":"CAPA結合矯正和預防措施以提高品質。"}]', '{"abbreviation":"CAPA (with corrective action)","adjective":"preventive"}', NULL, 5, 5126, NULL),
(5127, 'preventive care', '/prɪˈvɛntɪv kɛər/', 'noun', '{"zh-TW":["預防保健；預防性護理"],"en":["healthcare aimed at preventing illness rather than treating it"]}', NULL, 'invest in preventive care / preventive care program', '[{"en":"Regular screenings are an important part of preventive care.","zh-TW":"定期篩查是預防保健的重要組成部分。"},{"en":"Preventive care reduces long-term healthcare costs.","zh-TW":"預防保健降低了長期醫療費用。"}]', '{"adjective":"preventive","verb":"prevent"}', NULL, 5, 5127, NULL),
(5128, 'preventive medicine', '/prɪˈventɪv ˈmedsɪn/', 'noun', '{"zh-TW":["預防醫學"],"en":["the branch of medicine focused on preventing disease rather than treating it"]}', NULL, 'practice preventive medicine / preventive medicine approach / preventive medicine strategy', '[{"en":"Preventive medicine emphasizes lifestyle changes and regular screening.","zh-TW":"預防醫學強調生活方式改變和定期篩查。"},{"en":"Investing in preventive medicine reduces long-term healthcare costs.","zh-TW":"投資於預防醫學可以降低長期醫療保健費用。"}]', NULL, NULL, 5, 5128, NULL),
(5129, 'previous', '/ˈpriːviəs/', 'adjective', '{"zh-TW":["先前的；以前的"],"en":["happening before the current time"]}', '{"prefix":{"text":"pre-","meaning":"before"},"root":{"text":"vi","meaning":"way (路)"}}', 'previous experience / previous year / previous employer', '[{"en":"Do you have any previous experience?","zh-TW":"你有先前的經驗嗎？"},{"en":"Sales increased compared to the previous year.","zh-TW":"銷售比前一年增加了。"}]', '{"adverb":"previously"}', NULL, 3, 5129, 178),
(5130, 'price', '/praɪs/', 'noun', '{"zh-TW":["價格"],"en":["the amount of money for which something is sold"]}', '{"root":{"text":"price","meaning":"value (價值)"},"logic":"源自拉丁語 pretium（價值）。"}', 'price tag / asking price / price range', '[{"en":"The price of gas has gone up again.","zh-TW":"汽油價格又上漲了。"},{"en":"What is the price of this laptop?","zh-TW":"這台筆電的價格是多少？"}]', '{"adjective":"pricey","verb":"price"}', NULL, 2, 5130, NULL),
(5131, 'price ceiling', '/praɪs ˈsiːlɪŋ/', 'noun', '{"zh-TW":["價格上限"],"en":["a government-imposed maximum price for a good or service"]}', NULL, 'set a price ceiling / price ceiling regulation', '[{"en":"The government set a price ceiling on essential medicines.","zh-TW":"政府對基本藥物設置了價格上限。"},{"en":"A price ceiling below the market price creates shortages.","zh-TW":"低於市場價格的價格上限造成了短缺。"}]', '{"opposite":"price floor"}', NULL, 5, 5131, NULL),
(5132, 'price discrimination', '/praɪs ˌdɪskrɪmɪˈneɪʃən/', 'noun', '{"zh-TW":["價格歧視"],"en":["charging different prices to different customers for the same product"]}', NULL, 'practice price discrimination / first-degree price discrimination', '[{"en":"Airlines use price discrimination by charging different fares for the same seat.","zh-TW":"航空公司對同一座位收取不同票價，實行價格歧視。"},{"en":"Price discrimination maximizes revenue by capturing more consumer surplus.","zh-TW":"價格歧視通過獲取更多消費者剩餘來最大化收入。"}]', NULL, NULL, 5, 5132, NULL),
(5133, 'price elasticity', '/praɪs ˌɪlæsˈtɪsɪti/', 'noun', '{"zh-TW":["價格彈性"],"en":["the sensitivity of demand or supply to price changes"]}', NULL, 'measure price elasticity / high price elasticity', '[{"en":"Luxury goods typically have low price elasticity of demand.","zh-TW":"奢侈品通常具有低價格彈性需求。"},{"en":"Understanding price elasticity helps set optimal product pricing.","zh-TW":"了解價格彈性有助於設定最優產品定價。"}]', NULL, NULL, 5, 5133, NULL),
(5134, 'price floor', '/praɪs flɔːr/', 'noun', '{"zh-TW":["價格下限"],"en":["a government-imposed minimum price for goods or services"]}', NULL, 'set a price floor / minimum wage as price floor / agricultural price floor', '[{"en":"An agricultural price floor ensures farmers receive a minimum income for their crops.","zh-TW":"農業價格下限確保農民從其農作物中獲得最低收入。"},{"en":"A minimum wage is an example of a price floor in the labor market.","zh-TW":"最低工資是勞動力市場中價格下限的一個例子。"}]', NULL, NULL, 4, 5134, NULL),
(5135, 'price point', '/praɪs pɔɪnt/', 'noun', '{"zh-TW":["定價點；價格節點"],"en":["a specific price at which a product is sold"]}', NULL, 'set a price point / competitive price point', '[{"en":"The product was launched at an accessible price point to attract new users.","zh-TW":"產品以親民的定價點推出以吸引新用戶。"},{"en":"Premium brands target a high price point to reinforce quality perception.","zh-TW":"高端品牌針對高定價點以強化品質感知。"}]', NULL, NULL, 4, 5135, NULL),
(5136, 'price sensitivity', '/praɪs ˌsensɪˈtɪvɪti/', 'noun', '{"zh-TW":["價格敏感度"],"en":["the degree to which demand for a product changes in response to a price change"]}', NULL, 'measure price sensitivity / high price sensitivity', '[{"en":"In a commodity market, price sensitivity is very high.","zh-TW":"在商品市場中，價格敏感度非常高。"},{"en":"Understanding price sensitivity helps in setting optimal pricing strategies.","zh-TW":"了解價格敏感度有助於制定最佳定價策略。"}]', '{"synonym":"price elasticity"}', NULL, 5, 5136, NULL),
(5137, 'price tag', '/praɪs tæɡ/', 'noun', '{"zh-TW":["價格標籤"],"en":["a label showing the price of an item"]}', NULL, 'check the price tag / price tag information', '[{"en":"Always check the price tag before adding items to your cart.","zh-TW":"將商品加入購物車前請務必查看價格標籤。"},{"en":"The price tag showed the item was on sale.","zh-TW":"價格標籤顯示該商品正在促銷。"}]', NULL, NULL, 3, 5137, NULL),
(5138, 'price war', '/praɪs wɔːr/', 'noun', '{"zh-TW":["價格戰"],"en":["intense competition where businesses cut prices to gain market share"]}', NULL, 'avoid a price war / engage in a price war', '[{"en":"The price war between rivals eroded margins across the industry.","zh-TW":"競爭對手之間的價格戰侵蝕了整個行業的利潤率。"},{"en":"A price war benefits consumers in the short term but harms all competitors.","zh-TW":"價格戰在短期內有利於消費者，但對所有競爭者都有害。"}]', NULL, NULL, 3, 5138, NULL),
(5139, 'price-earnings ratio', '/praɪs ˈɜːrnɪŋz ˈreɪʃioʊ/', 'noun', '{"zh-TW":["本益比"],"en":["the ratio of a company''s share price to its earnings per share"]}', NULL, 'high price-earnings ratio / price-earnings ratio of 20', '[{"en":"A low price-earnings ratio may signal an undervalued stock.","zh-TW":"低本益比可能表示股票被低估。"},{"en":"The tech sector typically trades at a higher price-earnings ratio.","zh-TW":"科技行業通常以較高的本益比交易。"}]', '{"abbreviation":"P/E ratio"}', NULL, 5, 5139, NULL),
(5140, 'price-to-book ratio', '/praɪs tə bʊk ˈreɪʃiəʊ/', 'noun', '{"zh-TW":["市淨率"],"en":["the ratio comparing a company''s market value to its book value"]}', NULL, 'low price-to-book ratio / high price-to-book ratio / calculate price-to-book', '[{"en":"A low price-to-book ratio may indicate an undervalued stock.","zh-TW":"低市淨率可能表明股票被低估。"},{"en":"Value investors focus on companies with low price-to-book ratios.","zh-TW":"價值投資者關注市淨率低的公司。"}]', NULL, NULL, 5, 5140, NULL),
(5141, 'price-to-earnings ratio', '/praɪs tə ˈɜːrnɪŋz ˈreɪʃioʊ/', 'noun', '{"zh-TW":["本益比"],"en":["a valuation ratio comparing a company''s share price to its earnings per share"]}', NULL, 'calculate price-to-earnings ratio / low price-to-earnings ratio', '[{"en":"A high price-to-earnings ratio may indicate an overvalued stock.","zh-TW":"高本益比可能表明股票被高估了。"},{"en":"Investors compare the price-to-earnings ratio across industry peers.","zh-TW":"投資者比較同行業公司的本益比。"}]', '{"abbreviation":"P/E ratio"}', NULL, 5, 5141, NULL),
(5142, 'pricing', 'ˈpraɪsɪŋ', 'noun', '{"zh-TW":["定價；價格策略","標價"],"en":["the process of setting prices","a price structure"]}', NULL, 'competitive pricing/pricing strategy', '[{"en":"Our pricing strategy is very competitive.","zh-TW":"我們的定價策略非常有競爭力。"}]', '{"verb":"price","adjective":"priced"}', NULL, 3, 5142, NULL),
(5143, 'pricing model', '/ˈpraɪsɪŋ ˈmɒdəl/', 'noun', '{"zh-TW":["定價模型"],"en":["a structured approach for determining the price of a product or service"]}', NULL, 'develop a pricing model / dynamic pricing model', '[{"en":"The company switched to a subscription pricing model.","zh-TW":"公司切換到了訂閱定價模型。"},{"en":"A value-based pricing model focuses on perceived customer benefit.","zh-TW":"基於價值的定價模型側重於客戶感知的效益。"}]', NULL, NULL, 5, 5143, NULL),
(5144, 'pricing strategy', '/ˈpraɪsɪŋ ˈstrætədʒi/', 'noun', '{"zh-TW":["定價策略"],"en":["a method for setting the price of a product or service"]}', NULL, 'premium pricing strategy / penetration pricing strategy / competitive pricing strategy', '[{"en":"The company''s pricing strategy targets cost-conscious consumers.","zh-TW":"公司的定價策略針對注重成本的消費者。"},{"en":"Dynamic pricing strategy adjusts prices based on demand.","zh-TW":"動態定價策略根據需求調整價格。"}]', '{"verb":"price","adjective":"price-competitive"}', NULL, 5, 5144, NULL),
(5145, 'prima facie', '/ˌpraɪmə ˈfeɪʃi/', 'phrase', '{"zh-TW":["表面證據；初步推定"],"en":["at first sight; based on initial impression before deeper examination"]}', NULL, 'prima facie case / prima facie evidence / prima facie standard', '[{"en":"The prosecutor established a prima facie case for fraud.","zh-TW":"檢察官建立了欺詐的表面證據案件。"},{"en":"A prima facie case shifts the burden to the defendant to rebut.","zh-TW":"表面證據案件將舉證責任轉移給被告進行反駁。"}]', NULL, NULL, 4, 5145, NULL),
(5146, 'primarily', '/praɪˈmɛrəli/', 'adverb', '{"zh-TW":["主要地"],"en":["mainly; for the most part"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-arily","meaning":"副詞後綴"}}', 'primarily responsible / primarily focused on', '[{"en":"The company primarily focuses on B2B services.","zh-TW":"公司主要專注於B2B服務。"},{"en":"She is primarily responsible for marketing.","zh-TW":"她主要負責行銷。"}]', '{"adjective":"primary"}', NULL, 3, 5146, NULL),
(5147, 'primary', '/ˈpraɪmeri/', 'adjective', '{"zh-TW":["主要的；首要的"],"en":["most important; main"]}', '{"root":{"text":"prim","meaning":"first (第一)"},"suffix":{"text":"-ary","meaning":"...的"}}', 'primary goal / primary source / primary concern', '[{"en":"Our primary goal is customer satisfaction.","zh-TW":"我們的首要目標是客戶滿意。"},{"en":"Cost reduction is the primary concern.","zh-TW":"降低成本是首要關注。"}]', '{"adverb":"primarily"}', NULL, 3, 5147, 179),
(5148, 'primary care', '/ˈpraɪməri kɛər/', 'noun', '{"zh-TW":["基層醫療；初級保健"],"en":["general medical care by a doctor who is first consulted"]}', NULL, 'primary care physician / primary care provider', '[{"en":"Your primary care doctor handles routine health issues.","zh-TW":"您的基層醫療醫師處理例行健康問題。"},{"en":"Primary care is the first point of contact with the health system.","zh-TW":"基層醫療是與醫療體系的第一個接觸點。"}]', NULL, NULL, 4, 5148, NULL),
(5149, 'primary market', '/ˈpraɪməri ˈmɑːrkɪt/', 'noun', '{"zh-TW":["一級市場"],"en":["a market where new securities are issued directly to investors"]}', NULL, 'primary market offering / raise capital in primary market', '[{"en":"Companies raise capital in the primary market through IPOs.","zh-TW":"公司通過首次公開募股在一級市場籌集資金。"},{"en":"Primary market transactions involve the issuing company directly.","zh-TW":"一級市場交易直接涉及發行公司。"}]', '{"antonym":"secondary market"}', NULL, 5, 5149, NULL);